import timefrom typing import Any, Iterator, Optionalfrom google import genaifrom google.genai import typesfrom config import (    GEMINI_API_KEYS,    GEMINI_MODELS,    AI_TEMPERATURE,    AI_MAX_OUTPUT_TOKENS,    API_KEY_FAILOVER_DELAY_SECONDS,    MODEL_RETRY_COUNT,)# ============================================================# MafiyaAI AI Engine# ============================================================if not GEMINI_API_KEYS:    raise RuntimeError(        "No Gemini API key is configured."    )# ============================================================# Gemini Clients# ============================================================CLIENTS = []for api_key in GEMINI_API_KEYS:    try:        api_key = str(api_key).strip()        if not api_key:            continue        client = genai.Client(            api_key=api_key        )        CLIENTS.append(client)    except Exception:        continueif not CLIENTS:    raise RuntimeError(        "No usable Gemini API client could be created."    )# ============================================================# Model List# ============================================================MODELS = [    str(model_name).strip()    for model_name in GEMINI_MODELS    if model_name    and str(model_name).strip()]if not MODELS:    raise RuntimeError(        "No Gemini models are configured."    )# ============================================================# Generation Configuration# ============================================================GENERATION_CONFIG = types.GenerateContentConfig(    temperature=AI_TEMPERATURE,    max_output_tokens=AI_MAX_OUTPUT_TOKENS,)# ============================================================# Prepare Prompt# ============================================================def _prepare_prompt(    message: str,    conversation_context: Optional[str] = None,) -> str:    if message is None:        raise ValueError(            "Message cannot be None."        )    message = str(message).strip()    if not message:        raise ValueError(            "Message cannot be empty."        )    # AnswerBuilder provides the complete prompt.    if conversation_context:        prompt = str(            conversation_context        ).strip()    else:        prompt = message    if not prompt:        raise ValueError(            "Prompt cannot be empty."        )    return prompt# ============================================================# Safe String# ============================================================def _safe_string(value: Any) -> str:    if value is None:        return ""    try:        return str(value).strip()    except Exception:        return ""# ============================================================# Extract Part Text# ============================================================def _extract_part_text(    part: Any,) -> str:    if part is None:        return ""    # --------------------------------------------------------    # Object style    # --------------------------------------------------------    try:        text = getattr(            part,            "text",            None        )        if text:            text = _safe_string(                text            )            if text:                return text    except Exception:        pass    # --------------------------------------------------------    # Dictionary style    # --------------------------------------------------------    if isinstance(        part,        dict    ):        text = part.get(            "text"        )        if text:            text = _safe_string(                text            )            if text:                return text    return ""# ============================================================# Extract Response Text# ============================================================def extract_response_text(    response: Any,) -> str:    if response is None:        return ""    # ========================================================    # 1. Direct .text    # ========================================================    try:        text = getattr(            response,            "text",            None        )        if text:            text = _safe_string(                text            )            if text:                return text    except Exception:        pass    # ========================================================    # 2. Dictionary direct text    # ========================================================    if isinstance(        response,        dict    ):        direct_text = response.get(            "text"        )        if direct_text:            direct_text = _safe_string(                direct_text            )            if direct_text:                return direct_text    # ========================================================    # 3. Candidates    # ========================================================    candidates = None    try:        candidates = getattr(            response,            "candidates",            None        )    except Exception:        candidates = None    if candidates is None and isinstance(        response,        dict    ):        candidates = response.get(            "candidates"        )    if not candidates:        return ""    collected = []    # ========================================================    # Candidate Loop    # ========================================================    try:        for candidate in candidates:            content = None            # ------------------------------------------------            # Object candidate            # ------------------------------------------------            try:                content = getattr(                    candidate,                    "content",                    None                )            except Exception:                content = None            # ------------------------------------------------            # Dictionary candidate            # ------------------------------------------------            if content is None and isinstance(                candidate,                dict            ):                content = candidate.get(                    "content"                )            if content is None:                continue            # ------------------------------------------------            # Parts            # ------------------------------------------------            parts = None            try:                parts = getattr(                    content,                    "parts",                    None                )            except Exception:                parts = None            if parts is None and isinstance(                content,                dict            ):                parts = content.get(                    "parts"                )            if not parts:                continue            # ------------------------------------------------            # Extract parts            # ------------------------------------------------            for part in parts:                part_text = _extract_part_text(                    part                )                if part_text:                    collected.append(                        part_text                    )    except Exception:        pass    # ========================================================    # Final Text    # ========================================================    if collected:        result = "".join(            collected        ).strip()        if result:            return result    return ""# ============================================================# Response Diagnostic# ============================================================def _response_diagnostic(    response: Any,) -> str:    if response is None:        return "response=None"    diagnostics = [        f"type={type(response).__name__}"    ]    # --------------------------------------------------------    # Finish reason    # --------------------------------------------------------    try:        candidates = getattr(            response,            "candidates",            None        )        if candidates:            reasons = []            for candidate in candidates:                reason = getattr(                    candidate,                    "finish_reason",                    None                )                if reason is not None:                    reasons.append(                        str(reason)                    )            if reasons:                diagnostics.append(                    "finish_reason="                    + ",".join(reasons)                )    except Exception:        pass    # --------------------------------------------------------    # Prompt feedback    # --------------------------------------------------------    try:        prompt_feedback = getattr(            response,            "prompt_feedback",            None        )        if prompt_feedback is not None:            diagnostics.append(                "prompt_feedback="                + str(prompt_feedback)            )    except Exception:        pass    return " | ".join(        diagnostics    )# ============================================================# Error Classification# ============================================================def _error_status(    error: Exception,) -> str:    text = _safe_string(        error    ).lower()    if (        "503" in text        or "unavailable" in text        or "high demand" in text        or "temporarily unavailable" in text        or "service unavailable" in text    ):        return "503"    if (        "429" in text        or "resource exhausted" in text        or "rate limit" in text        or "quota" in text    ):        return "429"    if (        "500" in text        or "internal server error" in text    ):        return "500"    if (        "timeout" in text        or "timed out" in text    ):        return "timeout"    return "other"# ============================================================# Generate AI Response# ============================================================def generate_ai_response(    message: str,    conversation_context: Optional[str] = None,) -> str:    prompt = _prepare_prompt(        message,        conversation_context,    )    last_error = None    for key_index, client in enumerate(        CLIENTS,        start=1,    ):        for model_name in MODELS:            retry_count = max(                1,                int(MODEL_RETRY_COUNT),            )            for attempt in range(                retry_count            ):                try:                    response = (                        client.models.generate_content(                            model=model_name,                            contents=prompt,                            config=GENERATION_CONFIG,                        )                    )                    text = extract_response_text(                        response                    )                    if text:                        return text                    last_error = RuntimeError(                        f"API key {key_index}, "                        f"model {model_name}: "                        f"Gemini returned no AI text. "                        f"{_response_diagnostic(response)}"                    )                except Exception as error:                    last_error = error                    error_type = _error_status(                        error                    )                    # ------------------------------------------------                    # 503 / 429 / timeout                    # ------------------------------------------------                    #                    # These are normally transient, so continue                    # retry/failover instead of stopping.                    # ------------------------------------------------                    if error_type in {                        "503",                        "429",                        "500",                        "timeout",                    }:                        pass                    else:                        # Other errors are also allowed to                        # fail over to the next model/key.                        pass                # ------------------------------------------------                # Retry delay                # ------------------------------------------------                if (                    attempt < retry_count - 1                    and API_KEY_FAILOVER_DELAY_SECONDS > 0                ):                    time.sleep(                        API_KEY_FAILOVER_DELAY_SECONDS                    )    # ========================================================    # Everything Failed    # ========================================================    if last_error:        raise RuntimeError(            "All MafiyaAI Gemini API keys and models failed. "            f"Last error: {last_error}"        ) from last_error    raise RuntimeError(        "MafiyaAI could not generate a response."    )# ============================================================# Streaming AI Response# ============================================================def stream_ai_response(    message: str,    conversation_context: Optional[str] = None,) -> Iterator[str]:    prompt = _prepare_prompt(        message,        conversation_context,    )    last_error = None    # ========================================================    # API KEY    # ========================================================    for key_index, client in enumerate(        CLIENTS,        start=1,    ):        # ====================================================        # MODEL        # ====================================================        for model_name in MODELS:            retry_count = max(                1,                int(MODEL_RETRY_COUNT),            )            # ================================================            # RETRY            # ================================================            for attempt in range(                retry_count            ):                stream_started = False                try:                    response_stream = (                        client.models.generate_content_stream(                            model=model_name,                            contents=prompt,                            config=GENERATION_CONFIG,                        )                    )                    # ============================================                    # Receive chunks                    # ============================================                    for chunk in response_stream:                        chunk_text = (                            extract_response_text(                                chunk                            )                        )                        if not chunk_text:                            continue                        stream_started = True                        yield chunk_text                    # ============================================                    # Empty stream                    # ============================================                    if not stream_started:                        last_error = RuntimeError(                            f"API key {key_index}, "                            f"model {model_name}: "                            "Gemini returned no AI text "                            "during streaming."                        )                        continue                    # ============================================                    # Successful stream                    # ============================================                    return                except GeneratorExit:                    # User manually stopped streaming.                    return                except Exception as error:                    last_error = error                    error_type = _error_status(                        error                    )                    # ==================================================                    # IMPORTANT:                    #                    # Even if partial output was already received,                    # do NOT immediately terminate MafiyaAI.                    #                    # Move to the next model/API key.                    # ==================================================                    if error_type in {                        "503",                        "429",                        "500",                        "timeout",                    }:                        # Transient Gemini failure.                        pass                    else:                        # Other failure.                        # Still allow model/key failover.                        pass                # ================================================                # Retry delay                # ================================================                if (                    attempt < retry_count - 1                    and API_KEY_FAILOVER_DELAY_SECONDS > 0                ):                    time.sleep(                        API_KEY_FAILOVER_DELAY_SECONDS                    )        # ====================================================        # Next API key        # ====================================================        if (            key_index < len(CLIENTS)            and API_KEY_FAILOVER_DELAY_SECONDS > 0        ):            time.sleep(                API_KEY_FAILOVER_DELAY_SECONDS            )    # ========================================================    # Everything Failed    # ========================================================    if last_error:        raise RuntimeError(            "All MafiyaAI Gemini API keys and models failed "            "during streaming. "            f"Last error: {last_error}"        ) from last_error    raise RuntimeError(        "MafiyaAI could not generate a streaming response."    )# ============================================================# AI Connection Test# ============================================================def check_ai_connection() -> bool:    try:        response = generate_ai_response(            "Reply with exactly: OK"        )        return (            str(response).strip().upper()            == "OK"        )    except Exception:        return False# ============================================================# Get Available Models# ============================================================def get_available_models():    return list(        MODELS    )# ============================================================# AI Engine Status# ============================================================def get_ai_status():    return {        "configured": bool(            CLIENTS        ),        "api_key_count": len(            CLIENTS        ),        "models": get_available_models(),        "model_count": len(            MODELS        ),        "failover_delay_seconds":            API_KEY_FAILOVER_DELAY_SECONDS,        "retry_count":            MODEL_RETRY_COUNT,        "streaming":            True,        "message_limit":            None,        "memory_limit":            None,    }# ============================================================# Public Exports# ============================================================__all__ = [    "generate_ai_response",    "stream_ai_response",    "extract_response_text",    "check_ai_connection",    "get_available_models",    "get_ai_status",]